export async function identify(request, env, upstream = fetch) {
  const reply = (data, status = 200) => Response.json(data, {status, headers: {'cache-control':'no-store'}});
  if (request.method !== 'POST') return reply({error:'请提交一张植物照片。'},405);
  const origin = request.headers.get('origin');
  if (origin && origin !== new URL(request.url).origin) return reply({error:'请求来源不匹配。'},403);
  const key = env.PLANTNET_API_KEY || request.headers.get('x-plantnet-key');
  if (!key) return reply({code:'key',error:'请连接 Pl@ntNet 以开始识别。'},401);
  if (request.headers.get('content-type') !== 'image/jpeg') return reply({error:'请使用 JPEG 图像。'},415);
  const photo = await request.blob();
  if (!photo.size || photo.size > 4_000_000) return reply({error:'照片大小超出范围，请换一张。'},400);
  const form = new FormData();
  form.append('images',photo,'plant.jpg');
  const url = new URL('https://my-api.plantnet.org/v2/identify/all');
  url.search = new URLSearchParams({'api-key':key,lang:'zh','nb-results':'5'}).toString();
  try {
    const res = await upstream(url,{method:'POST',body:form,signal:AbortSignal.timeout(25000)});
    if ([401,403].includes(res.status)) return reply({code:env.PLANTNET_API_KEY?'config':'key',error:'识别密钥无效或权限不足，请检查 Pl@ntNet 配置。'},403);
    if (res.status === 404) return reply({results:[]});
    if (res.status === 429) return reply({error:'识别配额已用完，请稍后重试。'},429);
    if (!res.ok) return reply({error:'识别服务暂时不可用。'},502);
    const data = await res.json();
    const results = (data.results || []).filter(r=>r.species?.scientificNameWithoutAuthor).map(r=>({
      latin:r.species.scientificNameWithoutAuthor, name:r.species.commonNames?.[0] || r.species.scientificNameWithoutAuthor,
      score:r.score, family:r.species.family?.scientificNameWithoutAuthor || ''
    }));
    return reply({results});
  } catch {return reply({error:'连接识别服务超时或失败，请重试。'},503)}
}

const page="<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#faf9f5\"><title>植迹 · 农大校园植物手记</title><style>*{box-sizing:border-box}body{margin:0;background:#faf9f5;color:#233b2c;font-family:\"Microsoft YaHei\",system-ui,sans-serif}button,a{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}.shell{max-width:1320px;width:90%;margin:auto}header{background:#fdfcf8;border-bottom:1px solid #dddfd3}.bar,.brand,nav,.actions,.sectionTitle,footer{display:flex;align-items:center}.bar{height:76px;justify-content:space-between}.brand{gap:12px}.brand strong{font: bold 28px SimSun,serif;letter-spacing:2px}.brand small{border-left:1px solid #cbd0c4;padding-left:14px;color:#627266;letter-spacing:2px}.logo{background:#294d37;color:#fbf9e8;width:39px;height:39px;border-radius:12px;display:grid;place-items:center;font:36px Georgia;line-height:1}nav{height:100%;gap:32px}nav a{height:100%;display:flex;align-items:center;gap:7px;position:relative;font-size:15px;color:#68736a}nav a.active{color:#294a32;font-weight:bold}nav .active:after{content:\"\";height:3px;width:22px;background:#34573b;position:absolute;bottom:12px;left:calc(50% - 11px)}nav b{padding:2px 7px;border-radius:20px;background:#e7ebdf;font:12px Georgia}.hero{position:relative;isolation:isolate;overflow:hidden;background:linear-gradient(110deg,#e7edda,#e9edde 50%,#d2dfbd);border:1px solid #d8dfca;border-radius:20px;margin-top:30px}.heroCopy{position:relative;width:53%;padding:48px 0 48px 5%;pointer-events:none}.actions{gap:12px;flex-wrap:wrap;pointer-events:auto}.eyebrow{font:600 12px/1.4 Georgia,serif;letter-spacing:2.6px;color:#506746}.eyebrow span{display:inline-block;width:27px;height:1px;background:#69815d;vertical-align:middle;margin-right:8px}h1,h2,h3{font-family:\"Noto Serif SC\",\"Songti SC\",SimSun,serif}h1{font-size:clamp(42px,4.65vw,72px);line-height:1.18;letter-spacing:1px;margin:20px 0 14px}h1 em{font-style:normal;color:#507441}p{font-size:16px;line-height:1.8;color:#526351}.heroCopy p{margin:0 0 24px}.primary,.light{border:1px solid transparent;padding:12px 20px;border-radius:9px;display:inline-flex;gap:9px;align-items:center;justify-content:center;font-weight:600}.primary{background:#284d35;color:white}.light{border-color:#b6c4aa;background:#f7f9ef;color:#2d4934}button:hover,.card:hover{filter:brightness(.97)}button:focus-visible,a:focus-visible{outline:3px solid #b67935;outline-offset:3px}.heroArt{position:absolute;right:0;top:0;bottom:0;width:53%}.heroArt canvas{width:100%;height:100%;display:block}.heroArt i{position:absolute;bottom:6%;right:7%;font:italic 17px Georgia;color:#526545}.sectionTitle{justify-content:space-between;gap:14px;margin:38px 0 20px}.sectionTitle h2{font-size:32px;margin:6px 0 0}.meta{font-size:14px;color:#687668}.meta b{font:italic 18px Georgia;color:#3e5b46}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.card{border:1px solid #dcdfd1;border-radius:14px;overflow:hidden;text-align:left;background:#fffefa;padding:0;color:inherit;transition:transform .2s}.card:hover{transform:translateY(-3px)}.art{height:clamp(155px,15vw,220px);position:relative;overflow:hidden}.art canvas,.art img{width:100%;height:100%;object-fit:cover}.tag{position:absolute;left:15px;top:15px;background:#fffdf3db;padding:4px 10px;border-radius:20px;font-size:12px;color:#526242}.cardFoot{padding:18px 20px;display:flex;align-items:center;justify-content:space-between;gap:8px}.card h3{font-size:24px;margin:0 0 4px}.latin,i{font:italic 15px Georgia,serif;color:#65725f}.mark{border:1px solid #dde1d6;border-radius:50%;width:35px;height:35px;display:grid;place-items:center}.ico{display:inline-block;width:20px;height:20px;vertical-align:middle}footer{border-top:1px solid #dddfd4;padding:18px 0;margin:34px 0 0;justify-content:space-between;font-size:13px;color:#75806e}dialog{width:min(460px,92vw);max-height:90dvh;border:0;border-radius:18px;background:#faf9f5;color:#233b2c;padding:0;box-shadow:0 20px 90px #17271942}dialog::backdrop{background:#15261bb3}#close{position:absolute;z-index:2;right:12px;top:12px;background:#fffdf4;border:0;width:34px;height:34px;border-radius:50%;font-size:23px}.detailArt{width:100%;height:200px;object-fit:contain;display:block;background:#e9ebdd}.body{padding:24px}.body h2{margin:5px 0;font-size:30px}.body p{margin:12px 0}.body label{display:grid;gap:6px;font-size:14px;margin:14px 0}.body select,.body input{padding:10px;border-radius:7px;font:inherit;border:1px solid #cbd1c2;background:white}.body button.primary{width:100%}.empty{grid-column:1/-1;text-align:center;border:1px dashed #b9c8ad;padding:50px 12px;border-radius:15px;background:#eff2e7}.empty h2{margin:0}#toast:not(:empty){position:fixed;bottom:25px;left:50%;transform:translateX(-50%);padding:11px 19px;border-radius:20px;background:#294631;color:white}.recinfo{font-size:13px;color:#60705e;overflow-wrap:anywhere}[hidden]{display:none!important}\n@media(max-width:720px){.shell{width:92%}.brand small{display:none}.bar{height:62px}nav{gap:17px}.hero{margin-top:17px}.heroCopy{padding:28px 6% 25px;width:100%}.heroArt{width:58%;height:72%;top:5%;opacity:.85;right:-10%}.heroCopy h1{font-size:clamp(35px,8vw,50px)}.heroCopy p{font-size:14px;max-width:67%}.actions{gap:8px}.primary,.light{padding:11px 14px}.heroArt i{display:none}.sectionTitle{margin:26px 0 14px}.sectionTitle h2{font-size:26px}.cards{gap:12px;grid-template-columns:repeat(2,minmax(0,1fr))}.art{height:135px}.cardFoot{padding:12px}.card h3{font-size:21px}.mark{display:none}.tag{left:8px;top:8px}.latin{font-size:13px}.eyebrow{font-size:11px}.sectionTitle h1{font-size:32px}footer i{display:none}}\r\n.garden-stage{position:relative;background:radial-gradient(ellipse at 50% 52%,#fffced,#e4ead4 80%);overflow:hidden;border-radius:20px;border:1px solid #cad7bd}.garden-stage canvas{width:100%;height:clamp(340px,42vw,520px);display:block;touch-action:none;cursor:grab}.garden-stage canvas:active{cursor:grabbing}.scene-title,.scene-controls{position:absolute;display:flex;gap:5px}.scene-title{pointer-events:none;top:18px;left:22px;flex-direction:column}.scene-title small{color:#62705e;letter-spacing:2px;font:12px Georgia}.scene-title strong{font:600 19px SimSun,serif}.scene-controls{bottom:14px;right:15px}.scene-controls button{border:1px solid #b4c1a6;background:#fffdf4;color:#345038;border-radius:7px;min-width:38px;height:36px}.body a{text-decoration:underline;color:#356c48}.body select{max-width:100%}\r\n</style></head><body>\n<header><div class=\"shell bar\"><a class=\"brand\" href=\"#explore\"><span class=\"logo\">❧</span><strong>植迹</strong><small>校园植物手记</small></a><nav><a href=\"#explore\" id=\"ne\">植物探索</a><a href=\"#garden\" id=\"ng\">我的植物园 <b id=\"qty\">0</b></a></nav></div></header>\n<main class=\"shell\"><section id=\"explore\"><div class=\"hero\"><div class=\"heroArt\"><canvas id=\"heroCanvas\" aria-label=\"银杏枝叶的植物学插画\" role=\"img\"></canvas><i>Ginkgo biloba L.</i></div><div class=\"heroCopy\"><div class=\"eyebrow\"><span></span> CAMPUS FIELD NOTES</div><h1>遇见校园里的<br><em>每一片绿意。</em></h1><p>拍下身边的植物，辨认它的名字，<br>把每一次相遇收进你的专属植物园。</p><div class=\"actions\"><button class=\"primary\" id=\"shoot\"><span data-icon=\"camera\"></span>拍照识植</button><button class=\"light\" id=\"album\"><span data-icon=\"image\"></span>从相册选择</button></div></div></div>\n<div class=\"sectionTitle\"><div><div class=\"eyebrow\">BOTANICAL ATLAS</div><h2>校园植物图鉴</h2></div><span class=\"meta\">本期收录 <b>03</b> 种</span></div><div class=\"cards\" id=\"atlas\"></div></section>\n<section id=\"garden\" hidden><div class=\"sectionTitle\"><div><div class=\"eyebrow\">MY HERBARIUM</div><h1>我的植物园</h1><p>拖动环绕花园，点选植株查看你的校园观察记录。</p></div><button class=\"primary\" id=\"add\">＋ 记录植物</button></div><div class=\"garden-stage\"><canvas id=\"world\" tabindex=\"0\" aria-label=\"三维植物园。使用左右键旋转，上下键调整视角，加减键缩放。\"></canvas><div class=\"scene-title\"><small>CAMPUS CONSERVATORY</small><strong id=\"sceneLabel\">校园微景观</strong></div><div class=\"scene-controls\"><button id=\"smaller\" aria-label=\"缩小\">−</button><button id=\"larger\" aria-label=\"放大\">＋</button><button id=\"resetView\">复位</button></div></div><h2>观察手记</h2><div id=\"records\" class=\"cards\"></div></section>\n<footer><span>植迹 · 中国农业大学校园植物手记</span><i>Campus Herbarium</i></footer></main>\n<input type=\"file\" accept=\"image/*\" capture=\"environment\" hidden id=\"cam\"><input type=\"file\" accept=\"image/*\" hidden id=\"file\"><dialog id=\"modal\"><button id=\"close\" aria-label=\"关闭\">×</button><div id=\"content\"></div></dialog><div id=\"toast\" role=\"status\"></div>\n<script>const plants=[\n {name:'银杏',latin:'Ginkgo biloba L.',family:'银杏科',bg:'#e9ead1',colors:['#b5ba68','#738945','#516d39'],note:'看叶片上缘的小缺口。扇形的叶片从叶柄处展开，细细的叶脉反复分叉，秋日常转为金黄。'},\n {name:'鸡爪槭',latin:'Acer palmatum',family:'无患子科',bg:'#efe0d3',colors:['#d98a57','#ad583d','#803a30'],note:'叶片像一只张开的小手，通常分成五至七个尖裂片，边缘有细锯齿。秋叶常呈橙红色。'},\n {name:'垂柳',latin:'Salix babylonica L.',family:'杨柳科',bg:'#dee8db',colors:['#aec393','#789963','#466c50'],note:'沿着细长下垂的枝条找一找。叶片狭长，先端渐尖，中央有一条清楚的主脉。'}\n];\nfunction leafPath(id){\n const p=new Path2D();p.moveTo(0,0);\n if(id===0){\n p.bezierCurveTo(-5,-12,-48,-31,-62,-60);\n for(let i=0;i<=60;i++){let x=-62+i*124/60,y=-84+24*(x/62)**2+11*Math.exp(-((x/6)**2))+1.7*Math.sin(i*1.9);p.lineTo(x,y)}\n p.bezierCurveTo(50,-34,9,-15,0,0)\n }else if(id===1){\n const tips=[[-43,-4],[-61,-38],[-40,-65],[0,-100],[38,-67],[59,-40],[45,-8]],cuts=[[-24,-16],[-26,-28],[-12,-38],[12,-38],[27,-25],[25,-15],[0,0]];\n let a=[0,0];for(let j=0;j<7;j++){for(let b of [tips[j],cuts[j]]){for(let i=1;i<=10;i++){let t=i/10,d=i%2?1.8:0;p.lineTo(a[0]+(b[0]-a[0])*t+d,a[1]+(b[1]-a[1])*t-d)}a=b}}\n }else{p.bezierCurveTo(-14,-19,-11,-65,4,-109);p.bezierCurveTo(10,-72,17,-28,0,0)}\n p.closePath();return p;\n}\nfunction drawLeaf(c,id,x,y,s,r,tone=0){\n c.save();c.translate(x,y);c.rotate(r);c.scale(s,s);let p=leafPath(id),[light,mid,dark]=plants[id].colors;let g=c.createLinearGradient(-44,-80,45,-4);g.addColorStop(0,tone?mid:light);g.addColorStop(.55,tone?light:mid);g.addColorStop(1,dark);c.fillStyle=g;c.fill(p);c.strokeStyle=dark;c.lineWidth=.6;c.stroke(p);c.clip(p);c.strokeStyle=dark;c.globalAlpha=.46;c.lineWidth=.57;\n for(let i=-38;i<=38;i++){c.beginPath();if(id===0){const a=i*.021;c.moveTo(0,0);c.quadraticCurveTo(Math.sin(a)*35,-43,Math.sin(a)*132,-109*Math.cos(a))}else if(id===1){let tips=[[-43,-4],[-61,-38],[-40,-65],[0,-100],[38,-67],[59,-40],[45,-8]],k=(i+38)%7,q=Math.floor((i+38)/7)/11,[tx,ty]=tips[k];c.moveTo(0,0);c.lineTo(tx*q,ty*q);c.lineTo(tx*(q+.12)+(i%2?8:-8),ty*(q+.2))}else{let v=(i+38)/77;c.moveTo(v*4,-110*v);c.lineTo(i%2?13:-13,-110*v-12)}c.stroke()}c.restore()\n}\nfunction plate(canvas,id,hero=false){\n let W=hero?660:460,H=hero?410:210;canvas.width=W*2;canvas.height=H*2;let c=canvas.getContext('2d');c.scale(2,2);if(!hero){c.fillStyle=plants[id].bg;c.fillRect(0,0,W,H)}\n let seed=13;const rand=()=>((seed=seed*16807%2147483647)/2147483647);\n for(let i=0;i<4500;i++){c.fillStyle='rgba(69,76,43,'+(rand()*.13)+')';c.fillRect(rand()*W,rand()*H,rand()*1.4+.3,.7)}\n c.save();if(hero){c.translate(12,6);c.scale(1.44,1.91)}\n const stem=(a,b,d,e,width)=>{c.beginPath();c.moveTo(...a);c.bezierCurveTo(...b,...d,...e);c.lineWidth=width;c.lineCap='round';c.strokeStyle='#6d7148';c.stroke();c.lineWidth=width*.28;c.strokeStyle='#b8ac81';c.stroke()};\n if(id===0){stem([495,242],[420,173],[282,142],[135,104],3.7);\n let specs=[[355,163,365,109,.91,.45],[337,153,314,88,.92,-.22],[306,145,272,163,.9,-1.95],[277,139,251,104,.82,-.53],[239,132,207,79,.8,-.32],[211,124,167,143,.73,-1.9],[183,118,153,82,.75,-.6],[156,110,112,100,.68,-1.12],[394,181,409,151,.91,.79]];\n for(let [bx,by,x,y,s,r] of specs){stem([bx,by],[bx-2,by-3],[x+3,y+6],[x,y],1.6);drawLeaf(c,0,x,y,s,r,s<.8)}\n }else if(id===1){stem([459,216],[360,169],[265,122],[157,93],3);for(let [bx,by,x,y,s,r] of [[329,154,340,108,.97,.35],[284,132,245,147,.94,-1.89],[245,119,214,95,.95,-.32],[193,104,150,100,.73,-.97]]){stem([bx,by],[bx-10,by],[x+3,y+2],[x,y],1.5);drawLeaf(c,1,x,y,s,r)}}\n else{for(let j=0;j<3;j++){let x=170+j*88;stem([x+90,-30],[x+40,18],[x,118],[x-26,211],1.8);for(let k=0;k<8;k++){let t=k/8;drawLeaf(c,2,x+53-85*t,10+176*t,.48+.15*Math.sin(t*3),k%2?2.62:-2.43,k%3===1)}}}c.restore();\n}\r\n</script><script>// Low-poly meshes in world coordinates, rendered with an orthographic orbit camera.\nfunction gardenScene(canvas, inspect) {\n  const ctx = canvas.getContext('2d');\n  let meshes=[], hits=[], angle=.68, pitch=.53, zoom=1, extent=5, active=-1, layer=0;\n  const face=(vertices,color)=>meshes.push({vertices,color,owner:active,layer});\n  function ring(x,y,z,rx,rz,n,phase=0){\n    return Array.from({length:n},(_,i)=>{\n      const a=phase+2*Math.PI*i/n;\n      return [x+rx*Math.cos(a),y,z+rz*Math.sin(a)];\n    });\n  }\n  function loft(lower,upper,colors){\n    lower.forEach((p,i)=>{const j=(i+1)%lower.length;face([p,lower[j],upper[j],upper[i]],colors[i%colors.length])});\n    face(upper,colors[0]);\n  }\n  function box(x,y,z,w,h,d,colors){\n    const corners=[[x-w/2,y,z-d/2],[x+w/2,y,z-d/2],[x+w/2,y,z+d/2],[x-w/2,y,z+d/2]];\n    loft(corners,corners.map(([x,y,z])=>[x,y+h,z]),colors);\n  }\n  const bark=['#92704b','#785535','#ad875b'],gold=['#b5c85e','#9fb449','#d5d76c','#aaba51'],red=['#db8961','#bd6148','#eaaa71','#cb7553'],green=['#86ac77','#699865','#a3c18a','#78a06e'];\n  function crown(x,y,z,r,h,palette,phase){\n    const middle=ring(x,y+h*.44,z,r,r*.87,7,phase);\n    loft(ring(x,y,z,r*.48,r*.40,7,phase+.16),middle,palette);\n    loft(middle,ring(x+.09,y+h,z-.06,r*.23,r*.2,7,phase+.25),palette.slice(1).concat(palette[0]));\n  }\n  function tree(x,z,record){\n    const species=record.latin.toLowerCase();\n    const type=species.startsWith('ginkgo ')?0:species.startsWith('acer ')?1:species.startsWith('salix ')?2:3;\n    const palette=[gold,red,green,['#72ad80','#59936c','#93bd85','#68996d']][type];\n    loft(ring(x,.03,z,.17,.17,7),ring(x,1.55,z,.09,.09,7),bark);\n    for(let i=0;i<5;i++){\n      const a=i*2.4,dx=Math.cos(a)*.48,dz=Math.sin(a)*.48,y=1.05+.13*i;\n      loft(ring(x,y-.4,z,.09,.09,5),ring(x+dx,y+.24,z+dz,.05,.05,5),bark);\n      crown(x+dx,type===2?.61:y,z+dz,type===2?.41:.54,type===2?1.38:.8,palette,a);\n    }\n    crown(x,1.68,z,type===0?.62:.57,type===0?1.18:.84,palette,.1);\n  }\n  function build(records){\n    meshes=[];active=-1;layer=0;\n    const cols=Math.max(2,Math.ceil(Math.sqrt(records.length||3))),rows=Math.max(2,Math.ceil(records.length/cols));\n    const w=cols*2.35+2.8,d=rows*2.35+2.6;extent=Math.hypot(w,d)/2;\n    const soil=['#bd9972','#a98764','#cba982'],grass=['#acc983','#99b676','#b7d08f'];\n    box(0,-.65,0,w,.52,d,soil);layer=1;box(0,-.13,0,w+.04,.13,d+.04,grass);\n    layer=2;const pathX=-w/2+.86;\n    for(let i=0;i<Math.floor(d/.68);i++)box(pathX,.015,-d/2+.47+i*.68,.73,.05,.49,['#dfd4b0','#c9bb95']);\n    for(let i=0;i<cols;i++)for(let j=0;j<rows;j++){\n      const x=(i-(cols-1)/2)*2.35+.58,z=(j-(rows-1)/2)*2.35;\n      loft(ring(x,.011,z,.92,.78,10),ring(x,.08,z,.94,.8,10),['#c5b88c','#cfc499']);\n    }\n    layer=3;\n    for(let z of [-d/2+.5,d/2-.5]){\n      for(let dx of [-.48,.48])box(pathX+dx,.01,z,.12,1.1,.13,bark);\n      box(pathX,1.12,z,1.35,.18,.25,bark);\n    }\n    for(let i=0;i<records.length;i++){\n      active=i;tree((i%cols-(cols-1)/2)*2.35+.58,(Math.floor(i/cols)-(rows-1)/2)*2.35,records[i]);\n    }\n    active=-1;draw();\n  }\n  function draw(){\n    const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;\n    const ratio=Math.min(2,devicePixelRatio||1);\n    if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio)}\n    ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);\n    const scale=Math.min(w/(extent*2.24),h/(extent*1.70+1.8))*zoom;\n    const ca=Math.cos(angle),sa=Math.sin(angle),cp=Math.cos(pitch),sp=Math.sin(pitch);\n    const project=([x,y,z])=>{const depth=x*sa+z*ca;return [w/2+(x*ca-z*sa)*scale,h*.54+(depth*sp-y*cp)*scale,depth*cp+y*sp]};\n    const ordered=meshes.map(f=>{const p=f.vertices.map(project);return {...f,p,depth:p.reduce((n,v)=>n+v[2],0)/p.length}}).sort((a,b)=>a.layer-b.layer||a.depth-b.depth);\n    hits=[];\n    for(const f of ordered){const shape=new Path2D();f.p.forEach(([x,y],i)=>i?shape.lineTo(x,y):shape.moveTo(x,y));shape.closePath();ctx.fillStyle=ctx.strokeStyle=f.color;ctx.lineWidth=.55;ctx.fill(shape);ctx.stroke(shape);if(f.owner>=0)hits.push([shape,f.owner])}\n  }\n  let drag;\n  canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,a:angle,p:pitch,moved:false};canvas.setPointerCapture(e.pointerId)};\n  canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)drag.moved=true;angle=drag.a+dx*.009;pitch=Math.max(.23,Math.min(1.18,drag.p+dy*.006));draw()};\n  canvas.onpointercancel=()=>{drag=null};\n  canvas.onpointerup=e=>{if(drag&&!drag.moved){let rect=canvas.getBoundingClientRect();ctx.save();ctx.resetTransform();const hit=hits.slice().reverse().find(([p])=>ctx.isPointInPath(p,e.clientX-rect.left,e.clientY-rect.top));ctx.restore();if(hit)inspect(hit[1])}drag=null};\n  const resize=factor=>{zoom=Math.max(.62,Math.min(2.4,zoom*factor));draw()};\n  canvas.onwheel=e=>{e.preventDefault();resize(Math.exp(-Math.sign(e.deltaY)*.12))};\n  canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')angle-=.15;else if(e.key==='ArrowRight')angle+=.15;else if(e.key==='ArrowUp')pitch=Math.min(1.18,pitch+.1);else if(e.key==='ArrowDown')pitch=Math.max(.23,pitch-.1);else resize(e.key==='-'?.9:1.1);draw()};\n  $('larger').onclick=()=>resize(1.2);$('smaller').onclick=()=>resize(1/1.2);$('resetView').onclick=()=>{angle=.68;pitch=.53;zoom=1;draw()};\n  new ResizeObserver(draw).observe(canvas);return build;\n}\r\n</script><script>const $=id=>document.getElementById(id),modal=$('modal'),body=$('content'),key='cau.flora.records.v1';\nconst symbols={camera:'<path d=\"M3 8h4l2-3h6l2 3h4v12H3z\"/><circle cx=\"12\" cy=\"13\" r=\"3.5\"/>',image:'<rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><circle cx=\"8\" cy=\"9\" r=\"1\"/><path d=\"m4 17 5-5 4 3 3-4 5 6\"/>',leaf:'<path d=\"M19 4C8 3 3 8 6 15c4 7 15 1 13-11Z M4 21 15 9\"/>'};\nconst icon=k=>'<svg class=\"ico\" aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\" stroke-linecap=\"round\">'+symbols[k]+'</svg>';\ndocument.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));\n\r\nlet apiKey='', requestController, collection=[], illustrated=false;\nconst hosted='https://cau-campus-flora-notebook.bubblybox131.chatgpt.site/';\nfunction records(){\n  try{return JSON.parse(localStorage.getItem(key)||'[]').map(r=>({...plants[r.id],...r})).filter(r=>r.name&&r.latin&&r.photo?.startsWith('data:image/'))}catch{return []}\n}\nfunction esc(value){const el=document.createElement('span');el.textContent=String(value??'');return el.innerHTML}\nfunction show(html){body.innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0}\n$('close').onclick=()=>modal.close();\nmodal.addEventListener('close',()=>{if(!modal.open)requestController?.abort()});\nfunction caption(p){return '<div class=\"cardFoot\"><div><h3>'+esc(p.name)+'</h3><i class=\"latin\">'+esc(p.latin)+'</i></div><span class=\"mark\">'+icon('leaf')+'</span></div>'}\nfunction detail(r){\n  show('<img class=\"detailArt\" alt=\"观察照片\"><div class=\"body\"><div class=\"eyebrow\">'+(r.demo?'图鉴示例':esc(r.provider)||'校园观察')+'</div><h2>'+esc(r.name)+'</h2><i>'+esc(r.latin)+'</i><p>'+esc(r.note||r.family||'')+'</p><div class=\"recinfo\">'+esc(r.date)+' · '+esc(r.location||'未填写地点')+'</div></div>');\n  body.querySelector('img').src=r.photo;\n}\nconst drawGarden=gardenScene($('world'),i=>illustrated?atlasDetail(i):detail(collection[i]));\nfunction route(){\n  const garden=location.hash==='#garden';$('explore').hidden=garden;$('garden').hidden=!garden;\n  $('ne').classList.toggle('active',!garden);$('ng').classList.toggle('active',garden);\n  collection=records();illustrated=!collection.length;$('qty').textContent=collection.length;\n  if(!garden)return;\n  $('sceneLabel').textContent=illustrated?'示例花园 · 点选植株体验':'我的花园 · '+collection.length+' 株';\n  drawGarden(illustrated?plants:collection);\n  $('records').replaceChildren();\n  if(illustrated){$('records').innerHTML='<div class=\"empty\"><h2>种下你的第一株植物</h2><p>上方展示三种示例树形。收藏第一条记录，即可看到自己的花园。</p><button class=\"light\" id=\"first\">拍照识植</button></div>';$('first').onclick=guide}\n  collection.forEach(r=>{const b=document.createElement('button');b.className='card';b.innerHTML='<div class=\"art\"><img alt=\"\"><span class=\"tag\">'+(r.demo?'示例记录':'观察记录')+'</span></div>'+caption(r);b.querySelector('img').src=r.photo;b.onclick=()=>detail(r);$('records').append(b)});\n}\nfunction atlasDetail(id){\n  const p=plants[id];show('<canvas class=\"detailArt\"></canvas><div class=\"body\"><div class=\"eyebrow\">'+p.family+'</div><h2>'+p.name+'</h2><i>'+p.latin+'</i><p>'+p.note+'</p><button class=\"primary\" id=\"sample\">将图鉴示例种入花园</button></div>');\n  const canvas=body.querySelector('canvas');plate(canvas,id);$('sample').onclick=()=>confirmPlant([p],canvas.toDataURL('image/jpeg',.76),true);\n}\nplants.forEach((p,id)=>{const b=document.createElement('button');b.className='card';b.innerHTML='<div class=\"art\"><canvas></canvas><span class=\"tag\">'+p.family+'</span></div>'+caption(p);$('atlas').append(b);plate(b.querySelector('canvas'),id);b.onclick=()=>atlasDetail(id)});\nplate($('heroCanvas'),0,true);\nfunction confirmPlant(options,photo,demo){\n  show('<img class=\"detailArt\" alt=\"植物记录\"><div class=\"body\"><div class=\"eyebrow\">'+(demo?'图鉴示例':'Pl@ntNet · 识别候选')+'</div><h2>确认后种入花园</h2><label>植物名称<select id=\"species\"></select></label><p id=\"taxonomy\"></p><label>发现地点（选填）<input id=\"place\" maxlength=\"60\" placeholder=\"例如：东校区图书馆旁\"></label><button class=\"primary\" id=\"save\">种入我的植物园</button><p id=\"feedback\" role=\"status\"></p></div>');\n  body.querySelector('img').src=photo;\n  options.forEach((r,i)=>$('species').add(new Option(r.name+(Number.isFinite(r.score)?' · '+(100*r.score).toFixed(1)+'%':''),i)));\n  $('species').onchange=()=>{const r=options[Number($('species').value)];$('taxonomy').textContent=[r.latin,r.family].filter(Boolean).join(' · ')};$('species').onchange();\n  $('save').onclick=()=>{const p=options[Number($('species').value)];\n    const record={name:p.name,latin:p.latin,family:p.family,note:p.note,photo,demo,provider:demo?'图鉴示例':'Pl@ntNet',location:$('place').value.trim(),date:new Date().toLocaleDateString('zh-CN')};\n    try{localStorage.setItem(key,JSON.stringify([record,...records()]))}catch{$('feedback').textContent='设备存储不可用或已满，记录未保存。';return}\n    modal.close();location.hash='garden';route();\n  };\n}\nfunction guide(){\n  show('<div class=\"body\"><div class=\"eyebrow\">PL@NTNET</div><h2>拍下身边的植物</h2><p>让叶、花或果实清晰入镜。确认后，照片将发送至 Pl@ntNet 识别。</p><div class=\"actions\"><button class=\"primary\" style=\"width:auto\" id=\"take\">打开相机</button><button class=\"light\" id=\"choose\">选择照片</button></div></div>');\n  $('take').onclick=()=>$('cam').click();$('choose').onclick=()=>$('file').click();\n}\n$('shoot').onclick=$('add').onclick=guide;$('album').onclick=()=>$('file').click();\nfunction prepare(file){\n  const url=URL.createObjectURL(file);\n  return (async()=>{try{\n    const image=new Image();image.src=url;await image.decode();\n    const canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));\n    const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);\n    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw Error();\n    const thumb=document.createElement('canvas'),factor=Math.min(1,640/Math.max(canvas.width,canvas.height));thumb.width=Math.max(1,Math.round(canvas.width*factor));thumb.height=Math.max(1,Math.round(canvas.height*factor));thumb.getContext('2d').drawImage(canvas,0,0,thumb.width,thumb.height);\n    return {blob,photo:thumb.toDataURL('image/jpeg',.73)};\n  }finally{URL.revokeObjectURL(url)}})();\n}\nfunction preview(photo,title,inside){show('<img alt=\"待识别的植物\" class=\"detailArt\"><div class=\"body\"><div class=\"eyebrow\">PL@NTNET</div><h2>'+title+'</h2>'+inside+'</div>');body.querySelector('img').src=photo}\nasync function identifyPhoto(item){\n  requestController?.abort();const controller=new AbortController();requestController=controller;\n  preview(item.photo,'正在辨认植物','<p role=\"status\">正在查询 Pl@ntNet 物种库…</p>');\n  try{\n    const headers={'Content-Type':'image/jpeg'};if(apiKey)headers['x-plantnet-key']=apiKey;\n    const response=await fetch('/api/identify',{method:'POST',headers,body:item.blob,signal:controller.signal});\n    const data=await response.json();if(controller.signal.aborted)return;\n    if(data.code==='key'){\n      preview(item.photo,'连接识别服务','<p>'+esc(data.error)+' 密钥只在当前页面内存中使用。</p><label>Pl@ntNet API Key<input type=\"password\" id=\"token\" autocomplete=\"off\"></label><button class=\"primary\" id=\"connect\">连接并识别</button><p><a href=\"https://my.plantnet.org/\" target=\"_blank\" rel=\"noopener\">获取自己的 Pl@ntNet 密钥</a></p>');\n      $('connect').onclick=()=>{apiKey=$('token').value.trim();if(apiKey)identifyPhoto(item);else $('token').focus()};return;\n    }\n    if(!response.ok)throw Error(data.error||'识别服务暂时不可用。');\n    if(!data.results.length){preview(item.photo,'未找到匹配植物','<p>请靠近一朵花或一片完整的叶子重新拍摄。</p><button class=\"light\" id=\"again\">换张照片</button>');$('again').onclick=guide;return}\n    const options=data.results.map(r=>{const known=plants.find(p=>p.latin.startsWith(r.latin+' ')||p.latin===r.latin);return {...r,name:known?.name||r.name,note:known?.note}});\n    confirmPlant(options,item.photo,false);\n  }catch(e){if(controller.signal.aborted)return;preview(item.photo,'这次识别未完成','<p>'+esc(e.message)+'</p><button class=\"light\" id=\"retry\">重新识别</button>');$('retry').onclick=()=>identifyPhoto(item)}\n}\nfor(const input of [$('cam'),$('file')])input.onchange=async()=>{\n  const file=input.files[0];input.value='';if(!file)return;\n  try{const item=await prepare(file);\n    if(location.protocol==='file:'){preview(item.photo,'在线识别植物','<p>离线版支持种植图鉴示例。拍照识别请打开在线版并选择照片。</p><a href=\"'+hosted+'\">打开在线版</a>');return}\n    preview(item.photo,'识别这株植物','<p>将这张照片发送至 Pl@ntNet，获取候选物种。</p><button class=\"primary\" id=\"identify\">开始识别</button>');$('identify').onclick=()=>identifyPhoto(item);\n  }catch{show('<div class=\"body\"><h2>照片读取失败</h2><p>请尝试 JPG、PNG 或 WebP 格式。</p></div>')}\n};\nwindow.addEventListener('hashchange',route);route();\r\n\r\n</script></body></html>\r\n\r\n";
export default {fetch(request,env){const path=new URL(request.url).pathname;if(path==='/api/identify')return identify(request,env);if(path==='/'||path==='/index.html')return new Response(page,{headers:{'content-type':'text/html; charset=utf-8'}});return new Response('Not found',{status:404})}};